<article class="recipe"><div class="recipe-top"><div><p class="eyebrow"><?=$recipe['is_public']?'COMMUNITY RECIPE':'PRIVATE RECIPE'?></p><h1><?=e($recipe['title'])?></h1><p class="lede"><?=e($recipe['summary'])?></p><p class="byline">By <?=e($recipe['owner_name'])?><?php if($recipe['forked_from_id']):?> · Inspired by <a href="/recipes/<?=$recipe['forked_from_id']?>">recipe #<?=$recipe['forked_from_id']?></a><?php endif?></p></div><div class="actions"><?php $u=App\Auth::user();?><?php if($u&&(int)$u['id']===(int)$recipe['user_id']):?><a class="button" href="/recipes/<?=$recipe['id']?>/edit">Edit recipe</a><?php endif?><?php if($recipe['is_public']):?><?php if($u):?><form method="post" action="/recipes/<?=$recipe['id']?>/fork"><?=csrf()?><button class="secondary">Make my version</button></form><?php else:?><a class="button secondary" href="/login">Sign in to remix</a><?php endif?><?php endif?></div></div>
<?php if($photos):?><div class="gallery"><?php foreach($photos as $i=>$p):?><img src="/uploads/<?=e($p['filename'])?>" alt="Photo of <?=e($recipe['title'])?>" <?=$i===0?'class="featured"':''?>><?php endforeach?></div><?php endif?>
<div class="recipe-content"><section class="ingredients"><h2>Ingredients</h2><div class="prose"><?=nl2br(e($recipe['ingredients']))?></div></section><section><h2>Instructions</h2><div class="prose"><?=nl2br(e($recipe['instructions']))?></div><?php if($recipe['notes']):?><div class="notes"><h3>Cook’s notes</h3><div class="prose"><?=nl2br(e($recipe['notes']))?></div></div><?php endif?></section></div></article>
